/**
 * @ohos/dsh-ontology/injection — the app-facing record of one pinned-fact
 * injection.
 *
 * The model sees the injected user message; the phone does not: ACP exposes
 * assistant/tool updates, not the durable user message the plugin prepends in
 * `agent/pre-step`. This ledger is the bridge. One compact JSONL line per
 * actual injection (never per turn), so the chat can say "本轮带入 N 条记忆"
 * and show where they came from without reading the prompt or the database.
 *
 * Keep the shape in sync with `entry/src/main/ets/model/MemoryInjection.ets`.
 */

/** Injection is capped at the same order as the pinned prompt block. */
export const MAX_INJECTION_FACTS = 30;

/**
 * Build one ledger record.
 *
 * @param {object} input - `{sessionId, turn, step, facts, removed, now}`.
 * @param {string} input.sessionId - the conversation the agent belongs to.
 * @param {number} [input.turn] - runtime turn number.
 * @param {number} [input.step] - runtime step number.
 * @param {object[]} [input.facts] - public facts that were injected.
 * @param {boolean} [input.removed] - true when the snapshot was a removal notice.
 * @param {number} [input.now] - epoch ms; tests pin it.
 * @returns {object|null} compact record, or null without a session id.
 */
export function recordOf({ sessionId, turn, step, facts = [], removed = false, now = Date.now() }) {
	if (typeof sessionId !== "string" || sessionId.length === 0) {
		return null;
	}
	const kept = facts.slice(0, MAX_INJECTION_FACTS).map((fact) => ({
		p: String(fact.predicate ?? ""),
		o: String(fact.object ?? ""),
		q: String(fact.qualifier ?? ""),
		src: String(fact.source ?? ""),
		at: String(fact.observed_at ?? fact.valid_from ?? ""),
	}));
	return {
		v: 1,
		t: now,
		s: sessionId,
		turn: Number.isFinite(turn) ? turn : 0,
		step: Number.isFinite(step) ? step : 0,
		n: kept.length,
		removed: removed ? 1 : 0,
		f: kept,
	};
}

/** Serialize one record; short keys keep the phone-side file small. */
export function lineOf(record) {
	return JSON.stringify(record) + "\n";
}

/**
 * Which pinned facts disappeared between two snapshots.
 *
 * A removal is only visible to the app when the whole pinned set empties, so
 * an allergy deleted while the name remains would otherwise change behavior
 * silently. Compare fact ids (not values): `remember`/`correct` supersede a
 * single-value fact with a new id, so the old id is exactly the one to report.
 *
 * @param {object[]} [previous] - pinned facts injected last time.
 * @param {object[]} [current] - pinned facts about to be injected.
 * @returns {object[]} previous facts whose id is gone from current.
 */
export function removedPinned(previous = [], current = []) {
	const alive = new Set(current.map((fact) => fact.id));
	return previous.filter((fact) => !alive.has(fact.id));
}
